263	func (s *APIV1Service) UpdateAttachment(ctx context.Context, request *v1pb.UpdateAttachmentRequest) (*v1pb.Attachment, error) {
264		attachmentUID, err := ExtractAttachmentUIDFromName(request.Attachment.Name)
265		if err != nil {
266			return nil, status.Errorf(codes.InvalidArgument, "invalid attachment id: %v", err)
267		}
268		if request.UpdateMask == nil || len(request.UpdateMask.Paths) == 0 {
269			return nil, status.Errorf(codes.InvalidArgument, "update mask is required")
270		}
271		user, err := s.fetchCurrentUser(ctx)
272		if err != nil {
273			return nil, status.Errorf(codes.Internal, "failed to get current user: %v", err)
274		}
275		if user == nil {
276			return nil, status.Errorf(codes.Unauthenticated, "user not authenticated")
277		}
278		attachment, err := s.Store.GetAttachment(ctx, &store.FindAttachment{UID: &attachmentUID})
279		if err != nil {
280			return nil, status.Errorf(codes.Internal, "failed to get attachment: %v", err)
281		}
282		if attachment == nil {
283			return nil, status.Errorf(codes.NotFound, "attachment not found")
284		}
285		// Only the creator or admin can update the attachment.
286		if attachment.CreatorID != user.ID && !isSuperUser(user) {
287			return nil, status.Errorf(codes.PermissionDenied, "permission denied")
288		}
289	
290		currentTs := time.Now().Unix()
291		update := &store.UpdateAttachment{
292			ID:        attachment.ID,
293			UpdatedTs: &currentTs,
294		}
295		for _, field := range request.UpdateMask.Paths {
296			if field == "filename" {
297				if !validateFilename(request.Attachment.Filename) {
298					return nil, status.Errorf(codes.InvalidArgument, "filename contains invalid characters or format")
299				}
300				update.Filename = &request.Attachment.Filename
301			}
302		}
303	
304		if err := s.Store.UpdateAttachment(ctx, update); err != nil {
305			return nil, status.Errorf(codes.Internal, "failed to update attachment: %v", err)
306		}
307		return s.GetAttachment(ctx, &v1pb.GetAttachmentRequest{
308			Name: request.Attachment.Name,
309		})
310	}
